// 48 hours in milliseconds: 48*60*60*1000 | 5 mins: 5 * 60 * 1000

return items.map(item => {

  // --- Normalize Event Date ---
  const rawDate = item.json["Event Date"];
  if (typeof rawDate === "number") {
    const ms = (rawDate - 25569) * 86400 * 1000;
    item.json["Event Date"] = new Date(ms).toISOString().split("T")[0];
  } else if (typeof rawDate === "string") {
    const d = new Date(rawDate);
    if (!isNaN(d)) item.json["Event Date"] = d.toISOString().split("T")[0];
  }

  // --- Normalize Timestamp ---
  const rawTs = item.json["Timestamp"];
  if (rawTs !== undefined && !isNaN(rawTs)) {
    item.json["Timestamp"] = new Date((Number(rawTs) - 25569) * 86400 * 1000).toLocaleString("en-US", { timeZone: "America/New_York" });
  }

  return item;
});

function extractFileId(url) {
  if (!url || typeof url !== 'string' || url.trim() === '') return null;
  let m = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
  if (m && m[1].length >= 10) return m[1];
  m = url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (m && m[1].length >= 10) return m[1];
  return null;
}
const item = items[0].json;
const stageFileId = extractFileId((item['Stage Photo Upload'] || '').trim());
const damageFileId = extractFileId((item['Damaged Equipment/Other Photos'] || '').trim());
return [{
  json: {
    ...item,
    _stageFileId: stageFileId,
    _damageFileId: damageFileId,
    _hasStagePhoto: stageFileId !== null,
    _hasDamagePhoto: damageFileId !== null
  }
}];

const obs = $input.first().json.obs[0];
const units = $input.first().json.station_units || {};

// Tempest returns data in the station's configured display units, not metric.
// Zeigler Park station is configured imperial — wind in mph, distance in miles.
// If a station were ever set to metric, we'd need to convert. For now we trust the unit fields.

const windGust = obs.wind_gust ?? 0;
const windAvg  = obs.wind_avg ?? 0;
const lightningDistance = obs.lightning_strike_last_distance ?? null;
const lightningCount = obs.lightning_strike_count_last_3hr ?? 0;
const lightningLastEpoch = obs.lightning_strike_last_epoch ?? null;

// Defensive conversion — only convert if the station is reporting metric.
// units_wind: "mph" | "kph" | "mps" | "kts"
// units_distance: "mi" | "km"
const windUnit = (units.units_wind || "mph").toLowerCase();
const distUnit = (units.units_distance || "mi").toLowerCase();

const toMphFromUnit = (v, unit) => {
  if (unit === "mph") return v;
  if (unit === "kph") return v * 0.621371;
  if (unit === "mps") return v * 2.23694;
  if (unit === "kts") return v * 1.15078;
  return v;
};

const toMilesFromUnit = (v, unit) => {
  if (v === null) return null;
  if (unit === "mi") return v;
  if (unit === "km") return v * 0.621371;
  return v;
};

const windGustMph = Math.round(toMphFromUnit(windGust, windUnit));
const windAvgMph  = Math.round(toMphFromUnit(windAvg, windUnit));
const lightningMiles = lightningDistance === null ? null : Math.round(toMilesFromUnit(lightningDistance, distUnit));

// Lightning "last distance" alone is misleading — it's the most recent strike ever,
// possibly hours/days old. Gate alerts on count_last_3hr > 0 AND last_epoch is recent.
const nowEpoch = Math.floor(Date.now() / 1000);
const lightningRecent = lightningLastEpoch !== null && (nowEpoch - lightningLastEpoch) <= 1800; // 30 min window
const lightningActive = lightningCount > 0 && lightningRecent;

return [{
  json: {
    windGustMph,
    windAvgMph,
    lightningMiles,
    lightningCount,
    lightningRecent,
    lightningActive,
    raw: obs,
    units
  }
}];

const staticData = $getWorkflowStaticData('global');
const body = $input.first().json.body ?? $input.first().json;

// Normalize station ID — lowercase, spaces to underscores
const stationId = String(body.station_id ?? body.id ?? 'unknown')
  .toLowerCase()
  .replace(/\s+/g, '_');
const stationName = body.station_name ?? body.name ?? stationId;

if (!staticData.stations) {
  staticData.stations = {};
}

// Stamp last_seen; preserve last_alerted if it exists
staticData.stations[stationId] = {
  ...( staticData.stations[stationId] || {} ),
  id: stationId,
  name: stationName,
  last_seen: new Date().toISOString()
};

return [{
  json: {
    success: true,
    station_id: stationId,
    station_name: stationName,
    recorded_at: staticData.stations[stationId].last_seen
  }
}];

const staticData = $getWorkflowStaticData('global');
const now = new Date();
const THRESHOLD_MS = 30 * 60 * 1000;
const COOLDOWN_MS  = 30 * 60 * 1000;

if (!staticData.stations || Object.keys(staticData.stations).length === 0) {
  return [{ json: { overdueStations: [] } }];
}

const overdueStations = [];

for (const [id, station] of Object.entries(staticData.stations)) {
  const lastSeen  = new Date(station.last_seen);
  const elapsed   = now - lastSeen;
  const minutesAgo = Math.floor(elapsed / 60000);

  if (elapsed > THRESHOLD_MS) {
    const lastAlerted  = station.last_alerted ? new Date(station.last_alerted) : null;
    const shouldAlert  = !lastAlerted || (now - lastAlerted >= COOLDOWN_MS);

    if (shouldAlert) {
      overdueStations.push({ id, name: station.name, last_seen: station.last_seen, minutes_ago: minutesAgo });
      staticData.stations[id].last_alerted = now.toISOString();
    }
  }
}

return [{ json: { overdueStations, check_time: now.toISOString() } }];

const stations = $input.first().json.overdueStations;

const lines = stations.map(s => {
  const h = Math.floor(s.minutes_ago / 60);
  const m = s.minutes_ago % 60;
  const timeStr = h > 0 ? `${h}h ${m}m` : `${m}m`;
  const lastSeenStr = new Date(s.last_seen).toLocaleString('en-US', {
    timeZone: 'America/New_York',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit'
  });
  return `:warning: *${s.name}* — last seen ${timeStr} ago (${lastSeenStr} ET)`;
});

const count = stations.length;
const message = `:satellite: *Weather Station Alert*\n${
  count === 1 ? 'A station has' : `${count} stations have`
} not reported in over 30 minutes:\n\n${lines.join('\n')}`;

return [{ json: { message } }];

